const PRIMARY = [
 {id:'inicio',label:'Inicio',icon:'⌂',asset:'inicio.png'},
 {id:'asistente',label:'Asistente virtual',icon:'☏',asset:'asistente.png'},
 {id:'buscador',label:'Buscador',icon:'⌕',asset:'buscador.png'},
 {id:'mis-cosas',label:'Mis cosas',icon:'▤',asset:'mis_cosas.png'},
 {id:'calendario',label:'Calendario',icon:'▦',asset:'calendario.png'},
 {id:'recordatorios',label:'Recordatorios',icon:'♧',asset:'recordatorios.png'},
 {id:'mas',label:'Más opciones',icon:'•••',asset:'mas.png'}
];
const EXTRA = [
 ['configuracion','Configuración'], ['alejandria','Alejandría'],['codice','Códice'],['pdfs','PDF por materia'],
 ['plan','Plan de estudio'],['nuevo-evento','Agregar evento'],['nuevo-recordatorio','Nuevo recordatorio'],
 ['ayuda','Ayuda'],['compartir','Compartir'],['acerca','Acerca de']
];
const LINKS = {
 'SIU Guaraní':'https://guarani.uba.ar/cbc/',
 'Campus UBA XXI':'https://www.ubaxxicampusvirtual.uba.ar/my/courses.php',
 'Campus CBC':'https://cbccampusvirtual.uba.ar/login/index.php',
 'Open Library':'https://openlibrary.org/?lang=es',
 'Redalyc':'https://www.redalyc.org/',
 'Biblioteca FADU':'https://biblioteca.fadu.uba.ar/tiki/tiki-read_article.php?articleId=894',
 'Biblioteca Digital Mundial':'https://www.loc.gov/collections/world-digital-library/about-this-collection/',
 'Project Gutenberg':'https://www.gutenberg.org/',
 'Biblioteca Virtual Cervantes':'https://www.cervantesvirtual.com/',
 'Europeana':'https://www.europeana.eu/es',
 'Internet Archive':'https://archive.org/',
 'Altillo UBA XXI':'https://www.altillo.com/examenes/uba/ubaxxi/index.asp',
 'Altillo CBC':'https://www.altillo.com/examenes/uba/cbc/index.asp',
 'Altillo FADU':'https://www.altillo.com/examenes/uba/fadu/index.asp'
};
const ACADEMIC = [
 ['2026-11-02','2.º parcial de ICP2'],
 ['2026-11-02','Pedido de recuperatorio ICP2 · inicio'],
 ['2026-11-03','2.º parcial de Taller de Dibujo'],
 ['2026-11-03','Pedido de recuperatorio ICP2 · cierre'],
 ['2026-11-06','2.º parcial de Matemática']
];
const SUBJECTS_SEED=['ICP2','Matemática','Taller de Dibujo','IPC'];
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem('huba_proto_'+key))??fallback;}catch{return fallback;}}
const state={subjects:readLocal('subjects',SUBJECTS_SEED.map((name,i)=>({name,done:i===3}))),reminders:readLocal('reminders',[]),events:readLocal('events',[]),dark:readLocal('dark',false),large:readLocal('large',false),contrast:readLocal('contrast',false),messages:[{from:'bot',text:'¡Hola! 👋 Soy el asistente virtual de h.UBA. Puedo ayudarte a organizar materias, consultar recursos y registrar fechas.'}]};
const save=(key)=>localStorage.setItem('huba_proto_'+key,JSON.stringify(state[key]));
const byId=(id)=>document.getElementById(id);
const escapeHtml=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,to,extra='')=>`<button type="button" class="item" data-nav="${to}"><span class="ico">${extra||'›'}</span><span class="grow">${escapeHtml(label)}</span><span class="right">›</span></button>`;
const actionBtn=(label,action,extra='')=>`<button type="button" class="item" data-action="${action}"><span class="ico">${extra||'•'}</span><span class="grow">${escapeHtml(label)}</span><span class="right">›</span></button>`;
const external=(name,sub='Abrir recurso externo')=>`<a class="item" href="${LINKS[name]}" target="_blank" rel="noopener noreferrer"><span class="ico">↗</span><span class="grow">${escapeHtml(name)}<small>${escapeHtml(sub)}</small></span><span class="right">›</span></a>`;
const section=(title,body,tone='')=>`<section class="section-card ${tone}"><h3>${title}</h3>${body}</section>`;
const pageHead=(name,desc,back='mas')=>`<button class="back" type="button" data-nav="${back}">‹ Volver</button><h2 class="inner-heading">${name}</h2><p class="inner-subtitle">${desc}</p>`;
const field=(label,name,placeholder,type='text',value='')=>`<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" placeholder="${escapeHtml(placeholder)}" value="${escapeHtml(value)}" ${type==='date'?'':'maxlength="160"'} required></div>`;
const navHtml=()=>[['inicio','⌂','Inicio'],['buscador','⌕','Buscador'],['calendario','▦','Calendario'],['recordatorios','♧','Recordatorios'],['mas','•••','Más']].map(([id,icon,label])=>`<button type="button" class="${current===id?'active':''}" data-nav="${id}"><span class="sym">${icon}</span>${label}</button>`).join('');
let current='inicio', lastBase='inicio', currentHighlight=false, selectedReminder=null, selectedSubject=null;
function screenTitle(id){return PRIMARY.find(x=>x.id===id)?.label||EXTRA.find(x=>x[0]===id)?.[1]||id;}
function region(x,y,w,h,label,nav,callback){return {x,y,w,h,label,nav,callback};}
const baseNav=[
 region(134,1475,110,126,'Inicio','inicio'),region(275,1475,110,126,'Buscador','buscador'),
 region(415,1475,115,126,'Calendario','calendario'),region(554,1475,115,126,'Recordatorios','recordatorios'),
 region(694,1475,120,126,'Más opciones','mas')
];
function regions(id){
 let items=[...baseNav,region(727,155,85,90,'Más opciones','mas'),region(619,155,93,90,'Recordatorios','recordatorios')];
 if(id==='inicio') items.push(
 region(144,630,369,92,'Abrir asistente virtual','asistente'),
 region(131,823,216,165,'Asistente virtual','asistente'),region(359,823,214,165,'Buscador','buscador'),region(587,823,222,165,'Mis cosas','mis-cosas'),
 region(131,996,215,165,'Calendario','calendario'),region(359,996,214,165,'Recordatorios','recordatorios'),region(587,996,222,165,'Configuración','configuracion'),
 region(145,1270,206,164,'SIU Guaraní',null,()=>window.open(LINKS['SIU Guaraní'],'_blank','noopener')),
 region(360,1270,210,164,'Campus UBA XXI',null,()=>window.open(LINKS['Campus UBA XXI'],'_blank','noopener')),
 region(581,1270,212,164,'Campus CBC',null,()=>window.open(LINKS['Campus CBC'],'_blank','noopener')));
 if(id==='asistente')items.push(region(140,290,150,69,'Volver al inicio','inicio'),region(135,1045,494,88,'Escribir una consulta','chat'),region(730,1045,83,88,'Enviar pregunta','chat'),region(128,941,682,99,'Preguntas sugeridas','chat'),region(127,1191,679,90,'Organizar materias','plan'),region(127,1282,679,91,'Anotar fechas','nuevo-evento'),region(127,1380,679,90,'Explorar recursos','buscador'));
 if(id==='buscador')items.push(region(124,442,689,89,'Ingresar búsqueda','buscar-recursos'),region(125,540,680,328,'Alejandría','alejandria'),region(125,885,680,294,'Códice','codice'),region(125,1180,680,299,'PDF por materia','pdfs'));
 if(id==='mis-cosas')items.push(region(144,614,379,110,'Objetivos académicos','objetivos'),region(135,808,673,327,'Materias y seguimiento','plan'),region(134,1140,658,88,'Agregar materia','agregar-materia'),region(133,1249,661,221,'Seguimiento del progreso','progreso'));
 if(id==='calendario')items.push(region(585,478,227,240,'Agregar evento personal','nuevo-evento'),region(585,724,227,243,'Calendario académico','calendario-oficial'),region(145,1004,666,472,'Fechas importantes','detalle-fechas'));
 if(id==='recordatorios')items.push(region(125,477,675,556,'Administrar recordatorios','gestionar-recordatorios'),region(126,1052,676,435,'Nuevo recordatorio','nuevo-recordatorio'));
 if(id==='mas')items.push(region(126,469,683,224,'Configuración','configuracion'),region(126,705,683,229,'Ayuda y soporte','ayuda'),region(126,949,683,244,'Compartir','compartir'),region(126,1204,683,273,'Acerca de','acerca'));
 return items;
}
function hotspots(id){byId('hotspots').innerHTML=regions(id).map((r,idx)=>`<button type="button" class="hotspot" title="${escapeHtml(r.label)}" aria-label="${escapeHtml(r.label)}" style="left:${r.x/941*100}%;top:${r.y/1672*100}%;width:${r.w/941*100}%;height:${r.h/1672*100}%" ${r.nav?`data-nav="${r.nav}"`:`data-hotspot="${idx}"`}></button>`).join('');}
function showToast(msg){const el=byId('snackbar');el.textContent=msg;el.classList.add('visible');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('visible'),2400);}
function go(id,record=true){if(!id)return; if(!PRIMARY.some(p=>p.id===id)&&!EXTRA.some(e=>e[0]===id)&&!['buscar-recursos','chat','objetivos','agregar-materia','progreso','calendario-oficial','detalle-fechas','gestionar-recordatorios'].includes(id))id='inicio';current=id; if(PRIMARY.some(p=>p.id===id))lastBase=id; if(record)history.pushState({id},'',`#${encodeURIComponent(id)}`);render();}
function render(){const original=PRIMARY.find(p=>p.id===current);const picture=original?current:(lastBase||'inicio');byId('screen-image').src=`assets/${PRIMARY.find(p=>p.id===picture)?.asset||'inicio.png'}`;byId('screen-image').alt=`Pantalla ${screenTitle(current)} de h.UBA`;byId('overlay').classList.toggle('hidden',!!original);byId('hotspots').style.display=original?'block':'none';if(original){hotspots(current);}else{renderOverlay(current);}byId('current-title').textContent=screenTitle(current);document.querySelectorAll('.screen-menu button').forEach(btn=>btn.classList.toggle('active',btn.dataset.nav===current));}
function renderOverlay(id){let html=`<div class="phone-bar"><span>9:41</span><span class="mini-status">▮▮ ▰ 100%</span></div><header class="app-header"><div><div class="wordmark"><em>h.</em>UBA</div><p class="tagline">Tu vida universitaria<br>en una sola app</p></div><div class="head-buttons"><button class="round-icon" data-nav="recordatorios" aria-label="Recordatorios">♧</button><button class="round-icon" data-nav="mas" aria-label="Más">☻</button></div></header><div class="inner-page">${content(id)}</div><nav class="nav-mobile" aria-label="Navegación principal">${navHtml()}</nav>`;const el=byId('overlay');el.innerHTML=html;el.classList.toggle('dark',state.dark);el.classList.toggle('large-text',state.large);}
function content(id){switch(id){
 case 'configuracion':return pageHead('Configuración','Personalizá tu experiencia en h.UBA.')+section('Apariencia',`<div class="toggle-row"><div><strong>Modo noche</strong><small>Cambiá a una paleta oscura.</small></div><input aria-label="Modo noche" type="checkbox" data-setting="dark" ${state.dark?'checked':''}></div><div class="toggle-row"><div><strong>Alto contraste</strong><small>Refuerza la legibilidad de los textos.</small></div><input aria-label="Alto contraste" type="checkbox" data-setting="contrast" ${state.contrast?'checked':''}></div><div class="toggle-row"><div><strong>Texto más grande</strong><small>Aumenta la tipografía en el prototipo.</small></div><input aria-label="Texto más grande" type="checkbox" data-setting="large" ${state.large?'checked':''}></div>`, 'aqua')+section('Información',btn('Acerca de h.UBA','acerca','ⓘ')+btn('Preguntas frecuentes','ayuda','?'));
 case 'alejandria':return pageHead('Alejandría','Bibliotecas, libros y recursos digitales.', 'buscador')+section('Bibliotecas digitales',Object.keys(LINKS).filter(x=>['Open Library','Redalyc','Biblioteca FADU','Biblioteca Digital Mundial','Project Gutenberg','Biblioteca Virtual Cervantes','Europeana','Internet Archive'].includes(x)).map(x=>external(x)).join(''),'aqua');
 case 'codice':return pageHead('Códice','Ejemplos de parciales por sistema y facultad.','buscador')+section('Parciales externos',external('Altillo UBA XXI')+external('Altillo CBC')+external('Altillo FADU'),'cream');
 case 'pdfs':return pageHead('PDF por materia','Programas y materiales incluidos en el prototipo.','buscador')+section('Documentación',[
 ['ICP1','Organizador_ICP1.pdf'],['ICP2','Programa_ICP2.pdf'],['IPC','Programa_IPC.pdf'],['ICSE','Programa_ICSE.pdf']].map(([n,p])=>`<a class="item" href="materiales/${p}" target="_blank" rel="noopener noreferrer"><span class="ico">▤</span><span class="grow">${n}<small>Documento PDF</small></span><span class="right">↗</span></a>`).join(''),'violet');
 case 'plan':return pageHead('Plan de estudio','Registrá materias y seguí tus avances.','mis-cosas')+section('Materias CBC / FADU',state.subjects.map((s,i)=>`<div class="item"><input type="checkbox" data-subject="${i}" aria-label="Completar ${escapeHtml(s.name)}" ${s.done?'checked':''}><span class="grow">${escapeHtml(s.name)}<small>${s.done?'Completada':'En curso'}</small></span><button class="secondary-btn" data-remove-subject="${i}" aria-label="Eliminar ${escapeHtml(s.name)}">×</button></div>`).join(''),'aqua')+btn('Agregar materia','agregar-materia','+');
 case 'agregar-materia':return pageHead('Agregar materia','Incorporá una materia a tu plan.','plan')+`<form id="subject-form" class="section-card aqua">${field('Nombre de la materia','subject','Por ejemplo: ICP2')}<button class="primary-btn" type="submit">Guardar materia</button></form>`;
 case 'objetivos':return pageHead('Tu objetivo','Organizá tu recorrido universitario.','mis-cosas')+section('Objetivo actual','<h3>Aprobar el CBC este año</h3><p>Podés organizar las tareas necesarias a través del calendario, las materias y los recordatorios.</p>','cream')+btn('Ver plan de estudio','plan','▤');
 case 'progreso':{const total=state.subjects.length,done=state.subjects.filter(s=>s.done).length,pct=total?Math.round(done/total*100):0;return pageHead('Mi progreso','Seguimiento de las materias registradas.','mis-cosas')+section('Avance general',`<div class="progress-row"><div class="progress-ring" style="background:conic-gradient(#17bcb9 0 ${pct}%,#e3edf6 ${pct}%)"><span>${pct}%</span></div><p>${done} de ${total} materias completadas</p></div>`,'aqua')+btn('Editar materias','plan','▤');}
 case 'nuevo-evento':return pageHead('Agregar evento','Creá una fecha en tu calendario.','calendario')+`<form id="event-form" class="section-card aqua">${field('Nombre del evento','event_title','Parcial, entrega o trámite')}${field('Fecha','event_date','Elegí la fecha','date')}<button class="primary-btn" type="submit">Guardar evento</button></form>`;
 case 'calendario-oficial':return pageHead('Calendario académico','Fechas importantes del recorrido universitario.','calendario')+section('Noviembre 2026',ACADEMIC.map(([date,title])=>`<div class="item"><span class="ico">▦</span><span class="grow">${escapeHtml(title)}<small>${date.split('-').reverse().join('/')}</small></span></div>`).join(''),'aqua')+section('UBA XXI',`<a class="item" href="https://ubaxxi.uba.ar/calendario-academico/" rel="noopener noreferrer" target="_blank"><span class="ico">↗</span><span class="grow">Consultar calendario oficial</span></a>`);
 case 'detalle-fechas':return pageHead('Próximas fechas','Calendario y eventos cargados.','calendario')+section('Fechas registradas',[...ACADEMIC,...state.events.map(e=>[e.date,e.title])].sort((a,b)=>a[0].localeCompare(b[0])).map(([date,title])=>`<div class="item"><span class="ico">▦</span><span class="grow">${escapeHtml(title)}<small>${date.split('-').reverse().join('/')}</small></span></div>`).join(''),'aqua')+btn('Agregar evento','nuevo-evento','+');
 case 'nuevo-recordatorio':return pageHead('Nuevo recordatorio','No te olvides de tus pendientes.','recordatorios')+`<form id="reminder-form" class="section-card cream">${field('Descripción','reminder_title','Por ejemplo: Estudiar Matemática')}${field('Fecha','reminder_date','Elegí la fecha','date')}<button class="primary-btn" type="submit">Crear recordatorio</button></form>`;
 case 'gestionar-recordatorios':return pageHead('Gestionar recordatorios','Marcá tareas como completadas o eliminá pendientes.','recordatorios')+section('Mis tareas',state.reminders.length?state.reminders.map((r,i)=>`<div class="item"><input type="checkbox" data-reminder="${i}" aria-label="Completar recordatorio" ${r.done?'checked':''}><span class="grow">${escapeHtml(r.title)}<small>${escapeHtml(r.date||'Sin fecha')}</small></span><button class="secondary-btn" data-remove-reminder="${i}" aria-label="Eliminar recordatorio">×</button></div>`).join(''):'<p>Todavía no hay recordatorios personales guardados.</p>','aqua')+btn('Nuevo recordatorio','nuevo-recordatorio','+');
 case 'buscar-recursos':return pageHead('Buscar recursos','Filtrá bibliotecas, parciales y materiales.','buscador')+`<div class="form-field"><label for="resource-query">Buscar</label><input id="resource-query" type="search" placeholder="Materia, sitio o tema..." autocomplete="off"></div><div id="results">${searchResultHtml('')}</div>`;
 case 'chat':return pageHead('Asistente virtual','Orientación académica y organización personal.','asistente')+`<div id="chat-messages">${state.messages.map(m=>`<div class="section-card ${m.from==='bot'?'aqua':'cream'}"><p style="font-weight:700">${m.from==='bot'?'h.UBA':'Vos'}</p><p>${escapeHtml(m.text)}</p></div>`).join('')}</div><form id="chat-form" class="row-between" style="gap:8px;align-items:end"><div class="form-field" style="flex:1"><label for="chat-input">Tu pregunta</label><input id="chat-input" name="message" required maxlength="300" placeholder="Escribí tu consulta..."></div><button class="primary-btn" style="width:auto;margin-bottom:12px" type="submit">➤</button></form>`;
 case 'ayuda':return pageHead('Ayuda y soporte','Preguntas frecuentes sobre el uso de h.UBA.')+section('Preguntas frecuentes',`<details class="item"><summary>¿Necesito registrarme?</summary><p>No. La app funciona sin cuenta propia.</p></details><details class="item"><summary>¿Dónde se guardan mis datos?</summary><p>En el almacenamiento del navegador de este dispositivo.</p></details><details class="item"><summary>¿Cómo encuentro programas o apuntes?</summary><p>Desde Buscador, en Alejandría, Códice o PDF por materia.</p></details><details class="item"><summary>¿La app pertenece oficialmente a UBA?</summary><p>No, es un prototipo académico independiente.</p></details>`,'cream')+btn('Acerca de','acerca','ⓘ');
 case 'compartir':return pageHead('Compartir h.UBA','Accedé mediante enlace o código QR.')+section('Código QR',`<img src="assets/qr.png" alt="QR para abrir h.UBA" style="display:block;width:152px;height:152px;margin:15px auto"><p style="text-align:center">Escaneá para abrir la aplicación.</p><button class="primary-btn" data-action="copy-link">Copiar enlace</button><p style="text-align:center;word-break:break-all;margin-top:9px">https://mebisa.github.io/h.UBA/</p>`,'aqua');
 case 'acerca':return pageHead('Acerca de h.UBA','Información sobre el proyecto.')+section('h.UBA',`<h3>Tu vida universitaria en una sola app.</h3><p>Prototipo académico desarrollado por Patricia Retamozo para la materia Introducción al Conocimiento Proyectual 2.</p><p>La aplicación facilita la consulta de recursos académicos y la organización personal de materias, fechas y recordatorios.</p><p>No es un servicio oficial de la Universidad de Buenos Aires.</p>`,'violet')+btn('Compartir la app','compartir','↗');
 default:return pageHead('Pantalla','')+btn('Volver al inicio','inicio','⌂');
}}
function searchResultHtml(q){const ql=q.trim().toLowerCase(),items=[...Object.keys(LINKS).filter(x=>/Open Library|Redalyc|FADU|Digital Mundial|Gutenberg|Cervantes|Europeana|Archive|Altillo/.test(x)), 'ICP1','ICP2','IPC','ICSE'];let list=items.filter(x=>x.toLowerCase().includes(ql));return section(`${list.length} resultados`,list.length?list.map(x=>LINKS[x]?external(x):btn(x,'pdfs','▤')).join(''):'<p>No se encontraron coincidencias.</p>');}
function submitForm(form){const fd=new FormData(form);if(form.id==='subject-form'){state.subjects.push({name:String(fd.get('subject')).trim(),done:false});save('subjects');go('plan');showToast('Materia agregada');}if(form.id==='event-form'){state.events.push({title:String(fd.get('event_title')).trim(),date:String(fd.get('event_date'))});save('events');go('detalle-fechas');showToast('Evento guardado');}if(form.id==='reminder-form'){state.reminders.push({title:String(fd.get('reminder_title')).trim(),date:String(fd.get('reminder_date')),done:false});save('reminders');go('gestionar-recordatorios');showToast('Recordatorio creado');}if(form.id==='chat-form'){const msg=String(fd.get('message')).trim();if(!msg)return;state.messages.push({from:'user',text:msg});const low=msg.toLowerCase();let answer=low.includes('materia')?'En «Plan de estudio» podés agregar y completar materias. En Calendario podés registrar exámenes y entregas.':low.includes('cbc')?'El CBC es el Ciclo Básico Común de la UBA. Para fechas y trámites, consultá las plataformas oficiales.':low.includes('apunte')?'Encontrás materiales en Buscador, dentro de Alejandría, Códice y PDF por materia.':'Podés consultar recursos, registrar fechas, agregar recordatorios y organizar tus materias. Para datos institucionales, revisá los enlaces oficiales.';state.messages.push({from:'bot',text:answer});renderOverlay('chat');const p=byId('chat-messages');if(p)p.lastElementChild?.scrollIntoView({block:'nearest'});}}
byId('phone').addEventListener('click',ev=>{const hit=ev.target.closest('[data-nav],[data-action],[data-remove-reminder],[data-remove-subject],[data-hotspot]');if(!hit)return;if(hit.dataset.nav){go(hit.dataset.nav);return;}if(hit.dataset.hotspot){const regionItem=regions(current)[Number(hit.dataset.hotspot)];regionItem?.callback?.();return;}if(hit.dataset.action==='copy-link'){navigator.clipboard?.writeText('https://mebisa.github.io/h.UBA/').then(()=>showToast('Enlace copiado'),()=>showToast('Enlace: https://mebisa.github.io/h.UBA/'));return;}if(hit.dataset.removeSubject!=null){state.subjects.splice(Number(hit.dataset.removeSubject),1);save('subjects');renderOverlay(current);return;}if(hit.dataset.removeReminder!=null){state.reminders.splice(Number(hit.dataset.removeReminder),1);save('reminders');renderOverlay(current);return;}});
byId('phone').addEventListener('change',ev=>{if(ev.target.dataset.setting){state[ev.target.dataset.setting]=ev.target.checked;save(ev.target.dataset.setting);renderOverlay(current);}if(ev.target.dataset.subject!==undefined){state.subjects[Number(ev.target.dataset.subject)].done=ev.target.checked;save('subjects');renderOverlay(current);}if(ev.target.dataset.reminder!==undefined){state.reminders[Number(ev.target.dataset.reminder)].done=ev.target.checked;save('reminders');renderOverlay(current);}});
byId('phone').addEventListener('submit',ev=>{ev.preventDefault();submitForm(ev.target);});
byId('phone').addEventListener('input',ev=>{if(ev.target.id==='resource-query')byId('results').innerHTML=searchResultHtml(ev.target.value);});
function menuRender(){byId('screen-menu').innerHTML=PRIMARY.map((p,i)=>`<button type="button" data-nav="${p.id}"><span class="num">${i+1}</span>${escapeHtml(p.label)}</button>`).join('');byId('extra-menu').innerHTML=EXTRA.map(([id,label])=>`<button type="button" data-nav="${id}">${escapeHtml(label)}</button>`).join('');}
for(const id of ['screen-menu','extra-menu'])byId(id).addEventListener('click',ev=>{const btn=ev.target.closest('[data-nav]');if(btn)go(btn.dataset.nav);});
byId('reset').addEventListener('click',()=>go('inicio'));
byId('toggle-hotspots').addEventListener('click',()=>{currentHighlight=!currentHighlight;byId('phone').classList.toggle('show-hotspots',currentHighlight);byId('toggle-hotspots').setAttribute('aria-pressed',String(currentHighlight));});
window.addEventListener('popstate',()=>{current=decodeURIComponent(location.hash.replace(/^#/,''))||'inicio';render();});
window.addEventListener('hashchange',()=>{const hash=decodeURIComponent(location.hash.slice(1))||'inicio';if(hash!==current){current=hash;render();}});
menuRender();current=decodeURIComponent(location.hash.slice(1))||'inicio';if(!location.hash)history.replaceState({id:'inicio'},'','#inicio');render();
